// TriggerBatchWindow A stream trigger that fires once for the events of a batch (ADR-0040 §4).
//
// The batch opens with its first event and fires when “window“ has passed or
// “max_events“ have joined, whichever comes first. Either may be left out;
// a batch never holds more than the deployment's cap.
type TriggerBatchWindow struct {
	// MaxEvents Fire as soon as this many events have joined.
	MaxEvents *int `json:"max_events"`

	// Window How long a batch stays open after its first event, e.g. '1h'.
	Window *string `json:"window"`
}

// TriggerSession What happens to the next event of the same session (ADR-0040 §4).
type TriggerSession struct {
	// Continue The next event with the same session_key joins the same task; null takes the source type's default (continue when it has sessions).
	Continue *bool `json:"continue"`

	// IdleTimeout How long the task waits for the next event, e.g. '30m'.
	IdleTimeout *string `json:"idle_timeout"`
}

// TriggerSpec Everything about a trigger except the agent it fires.
//
// A trigger fires an agent — on a cron schedule (“trigger_type='cron'“) or on
// the events of a stream (“trigger_type='stream'“). A webhook or a polled
// provider is a source of a stream (“streams_create_source“) with a stream
// trigger on it. Creating an agent takes a list of these, because the agent
// does not exist yet when they are written.
type TriggerSpec struct {
	// Batch Fire once for a batch of events instead of once per event: {"window": "1h", "max_events": 50} fires when the hour has passed or 50 events joined, whichever comes first. Null fires on every event.
	Batch *TriggerBatchWindow `json:"batch"`

	// Conditions Optional conditions evaluated against event data before firing. An LLM condition ({"type": "llm", "description": ...}) must name the chat or decision model instance that evaluates it in "model_id"; each sub-condition of a combined condition names its own.
	Conditions *map[string]interface{} `json:"conditions,omitempty"`

	// CronExpression 5- or 6-field cron expression (required when trigger_type='cron').
	CronExpression *string `json:"cron_expression"`

	// Description Short summary of what this trigger does.
	Description *string `json:"description,omitempty"`

	// Enabled Whether the trigger is active immediately on creation.
	Enabled *bool `json:"enabled,omitempty"`

	// EventFilter Which events of the stream fire it: {"kinds": ["push"], "fields": {"raw_data.action": "opened"}}. Empty means every event.
	EventFilter *map[string]interface{} `json:"event_filter"`

	// FailureThreshold Auto-disable after this many consecutive failed executions.
	FailureThreshold *int `json:"failure_threshold,omitempty"`

	// Name Human-readable trigger name.
	Name string `json:"name"`

	// Session What the next event of the same session does: {"continue": true, "idle_timeout": "30m"} joins the running task. Null takes the source type's default.
	Session *TriggerSession `json:"session"`

	// StreamId Stream whose events fire this trigger (required when trigger_type='stream').
	StreamId *openapi_types.UUID `json:"stream_id"`

	// TaskDefinitionId Saved task the trigger runs, of the same agent: its text and parameters are what each firing asks, in place of task_parameters.
	TaskDefinitionId *openapi_types.UUID `json:"task_definition_id"`

	// TaskParameters Parameters merged into the task created when the trigger fires.
	TaskParameters *map[string]interface{} `json:"task_parameters,omitempty"`

	// Timezone IANA timezone for cron evaluation (e.g. 'UTC', 'America/New_York').
	Timezone *string `json:"timezone,omitempty"`

	// TriggerType 'cron' for scheduled, 'stream' to run on the events of a stream (a webhook or a polled provider is a source of a stream).
	TriggerType TriggerSpecTriggerType `json:"trigger_type"`
}

